* { 
  margin: 0; 
  padding: 0; 
  box-sizing: border-box; 
}
body {
  background: #0a0a0a;
  font-family: 'Impact', 'Arial Black', sans-serif;
  overflow: hidden;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}
.container {
  width: 1280px;
  height: 720px;
  position: relative;
  background: #0a0a0a;
}
/* 放射状线条背景 */
.radiating-lines {
  position: absolute;
  top: 50%; 
  left: 50%;
  width: 100%; 
  height: 100%;
  transform: translate(-50%, -50%);
  background: repeating-conic-gradient(
    from 0deg,
    transparent 0deg,
    transparent 8deg,
    rgba(212,168,83,0.04) 8deg,
    rgba(212,168,83,0.04) 9deg
  );
}
/* 齿轮装饰 */
.bg-gear {
  position: absolute;
  border: 2px solid rgba(85,85,85,0.15);
  border-radius: 50%;
}
.bg-gear::before {
  content: '';
  position: absolute;
  inset: -5px;
  border: 1px dashed rgba(85,85,85,0.1);
  border-radius: 50%;
}
.gear-1 { 
  width: 200px; 
  height: 200px; 
  top: 20px; 
  left: 20px; 
}
.gear-2 { 
  width: 150px; 
  height: 150px; 
  bottom: 20px; 
  right: 20px; 
}
.title {
  position: absolute;
  top: 60px; 
  left: 50%;
  transform: translateX(-50%);
  color: #fff;
  font-size: 32px;
  font-weight: 900;
  letter-spacing: 2px;
  text-shadow: 3px 3px 0 #c0392b;
}
.subtitle {
  position: absolute;
  top: 110px; 
  left: 50%;
  transform: translateX(-50%);
  color: #888;
  font-size: 16px;
  font-style: italic;
}
.chart {
  position: absolute;
  top: 160px; 
  left: 80px;
  width: 1100px; 
  height: 480px;
}
.bar-row {
  display: flex;
  align-items: center;
  margin-bottom: 20px;
  opacity: 0;
  transform: translateX(-50px);
  animation: slideIn 0.6s ease forwards;
}
.year-label {
  width: 60px;
  color: #888;
  font-size: 14px;
  font-weight: bold;
  text-align: right;
  margin-right: 20px;
}
.bar-container {
  flex: 1;
  height: 40px;
  background: rgba(255,255,255,0.05);
  position: relative;
}
.bar {
  height: 100%;
  width: 0;
  position: relative;
  animation: growBar 1s ease forwards;
  border: 2px solid #fff;
}
.bar-value {
  position: absolute;
  right: -60px;
  top: 50%;
  transform: translateY(-50%);
  color: #fff;
  font-size: 14px;
  font-weight: bold;
  opacity: 0;
  animation: fadeIn 0.3s ease forwards;
}
.danger-line {
  position: absolute;
  top: 380px; 
  left: 160px;
  width: 900px; 
  height: 2px;
  background: repeating-linear-gradient(
    90deg,
    #c0392b 0px,
    #c0392b 10px,
    transparent 10px,
    transparent 20px
  );
  opacity: 0.5;
}
.danger-label {
  position: absolute;
  top: 350px; 
  left: 160px;
  color: #c0392b;
  font-size: 12px;
  font-weight: bold;
  opacity: 0.7;
}
.big-number {
  position: absolute;
  bottom: 40px; 
  right: 60px;
  font-size: 120px;
  font-weight: 900;
  color: #c0392b;
  opacity: 0;
}
@keyframes slideIn {
  to { 
    opacity: 1; 
    transform: translateX(0); 
  }
}
@keyframes growBar {
  to { 
    width: var(--target-width); 
  }
}
@keyframes fadeIn {
  to { 
    opacity: 1; 
  }
}
@keyframes pulseNum {
  0%, 100% { 
    opacity: 0.1; 
    transform: scale(1); 
  }
  50% { 
    opacity: 0.2; 
    transform: scale(1.05); 
  }
